UPDATE courses SET
    course_description = '<div class="content"> <p>This qualification reflects the role of highly skilled senior managers who use a broad range of hospitality skills combined with specialised managerial skills and substantial knowledge of industry to coordinate hospitality operations. They operate with significant autonomy and are responsible for making strategic business management decisions.</p> <p>This qualification provides a pathway to work in any hospitality industry sector and for a diversity of employers including restaurants, hotels, motels, catering operations, clubs, pubs, cafés, and coffee shops. This qualification allows for multi-skilling and for acquiring targeted skills in accommodation services, cookery, food and beverage and gaming.</p> <p>The skills in this qualification must be applied in accordance with Commonwealth and State/Territory legislation, Australian standards and industry codes of practice.</p> <p>No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p> </div>',
    total_course_duration = '104 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="content"> <p>There is no pre-requisites or specific entry requirement for this qualification. This course is available to all international students as along as they can provide the evidence that:</p> <ul> <li aria-level="1">The Student must be 18 years or older at the time of course commencement,</li> <li aria-level="1">The Student has successfully completed the Australian Year 12 (or equivalent) and,</li> <li aria-level="1">The Student have an IELTS score of at least 6.0 or PTE Academic score of 50 (or equivalent) OR Successful completion of ELICOS (English for Academic Purposes (EAP) or General English) at Advanced level.</li> <li aria-level="1">Note: Citizens of certain countries are exempted from the English proficiency requirement, please contact AIA for further details or visit the <a href="https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility" rel="noopener" target="_blank">DOHA Website</a>.</li> </ul> </div>',
    apply_form = 'https://auscanus.edu.au/courses/advanced-diploma-of-hospitality-management/',
    updated_at = NOW()
WHERE cricos_course_code = '114256F';

UPDATE courses SET
    course_description = '<div class="content"> <p>This qualification reflects the role of individuals in a range of community settings and peoples’ homes, who provide support in a manner that empowers people with disabilities to achieve greater levels of independence, self-reliance, community participation and wellbeing. Workers promote a person-centred approach, work according to and may contribute to an individualised plan, and work without direct supervision. They may be required to supervise and/or coordinate a small team.</p> <p>The skills in this qualification must be applied in accordance with Commonwealth and State/Territory legislation, Australian standards and industry codes of practice.</p> </div>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="content"> <p>This course is available to all international students and there are no specific entry requirements as per the qualification details or training packages. However, the student must meet the following entry requirements;</p> <ul> <li>The Student must be 18 years or older at the time of course commencement and,</li> <li>The Student have an IELTS score of at least 6.0 <strong>OR</strong> TOEFL IBT 60 <strong>OR</strong> PTE Academic score of 50 (or equivalent) <strong>OR </strong>A minimum of two (2) years of study at an AQF Level 4 or higher completed in Australia <strong>OR</strong> as per below.</li> </ul> <p>English language competence can also be demonstrated through documented evidence of any of the following:</p> <ul> <li>Minimum five (5) years of study in English in Australia, Canada, New Zealand, Britain, America, South America or Ireland.</li> <li>Completed in Australia in English a substantial component (at least 50%) of a qualification at AQF level 5 or higher.</li> <li>Completed in Australia in English Year 12 of secondary school.</li> <li>Completed a recognised ELICOS program and achieved an English Proficiency level of upper intermediate or equivalent.</li> <li>Applicants without the documented evidence to demonstrate the required English language competence may undertake the Language Literacy and Numeracy (LLN) test online to achieve a result of ACSF level 4-5 to meet Auscanus Institute of Australia’s entry requirement.</li> </ul> <p>Note: Citizens of certain countries are exempted from the English proficiency requirement, please contact AIA for further details or visit the <a href="https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility" rel="noopener" target="_blank">DOHA Website</a>.</p> </div>',
    apply_form = 'https://auscanus.edu.au/courses/certificate-iv-in-disability-support/',
    updated_at = NOW()
WHERE cricos_course_code = '118321C';

UPDATE courses SET
    course_description = '<div class="content"> <p>This qualification reflects the role of support workers who complete specialised tasks and functions in aged services; either in residential, home or community-based environments. Workers will take responsibility for their own outputs within defined organisation guidelines and maintain quality service delivery through the development, facilitation and review of individualised service planning and delivery.</p> <p>Workers may be required to demonstrate leadership and have limited responsibility for the organisation and the quantity and quality of outputs of others within limited parameters.</p> <p>To achieve this qualification, the candidate must have completed at least 120 hours of work as detailed in the Assessment Requirements of the units of competency.</p> </div>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="content"> <p>This course is available to all international students and there are no specific entry requirements as per the qualification details or training packages. However, the student must meet the following entry requirements;</p> <ul> <li>The Student must be 18 years or older at the time of course commencement and,</li> <li>The Student have an IELTS score of at least 6.0 <strong>OR</strong> TOEFL IBT 60 <strong>OR</strong> PTE Academic score of 50 (or equivalent) <strong>OR </strong>A minimum of two (2) years of study at an AQF Level 4 or higher completed in Australia <strong>OR</strong> as per below.</li> </ul> <p>English language competence can also be demonstrated through documented evidence of any of the following:</p> <ul> <li>Minimum five (5) years of study in English in Australia, Canada, New Zealand, Britain, America, South America or Ireland.</li> <li>Completed in Australia in English a substantial component (at least 50%) of a qualification at AQF level 5 or higher.</li> <li>Completed in Australia in English Year 12 of secondary school.</li> <li>Completed a recognised ELICOS program and achieved an English Proficiency level of upper intermediate or equivalent.</li> <li>Applicants without the documented evidence to demonstrate the required English language competence may undertake the Language Literacy and Numeracy (LLN) test online to achieve a result of ACSF level 4-5 to meet Auscanus Institute of Australia’s entry requirement.</li> </ul> <p>Note: Citizens of certain countries are exempted from the English proficiency requirement, please contact AIA for further details or visit the <a href="https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility" rel="noopener" target="_blank">DOHA Website</a>.</p> </div>',
    apply_form = 'https://auscanus.edu.au/courses/certificate-iv-in-ageing-support/',
    updated_at = NOW()
WHERE cricos_course_code = '118320D';

UPDATE courses SET
    course_description = '<div class="content"> <p>This qualification reflects the role of individuals who apply specialised knowledge and skills, together with experience in leadership and management, across a range of enterprise and industry contexts.</p> <p>Individuals at this level use initiative and judgement to plan and implement a range of leadership and management functions, with accountability for personal and team outcomes within broad parameters.</p> <p>They use cognitive and communication skills to identify, analyse and synthesise information from a variety of sources and transfer their knowledge to others, and creative or conceptual skills to express ideas and perspectives or respond to complex problems.</p> </div>',
    total_course_duration = '78 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="content"> <p>This course is available to all international students – However, the entry to this course is limited to those who have:</p> <ul> <li>Completed a Diploma or Advanced Diploma from the BSB Training Package (current or superseded equivalent versions) or/</li> <li>Have two years equivalent full-time relevant workplace experience in an operational or leadership role in an enterprise.</li> </ul> <p>The student also must provide the evidence that:</p> <ul> <li aria-level="1">The Student must be 18 years or older at the time of course commencement,</li> <li aria-level="1">The Student has successfully completed the Australian Year 12 (or equivalent) and,</li> <li aria-level="1">The Student have an IELTS score of at least 6.0 or PTE Academic score of 50 (or equivalent) OR Successful completion of ELICOS (English for Academic Purposes (EAP) or General English) at Advanced level.</li> <li aria-level="1">Note: Citizens of certain countries are exempted from the English proficiency requirement, please contact AIA for further details or visit the <a href="https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility" rel="noopener" target="_blank">DOHA Website</a>.</li> </ul> </div>',
    apply_form = 'https://auscanus.edu.au/courses/advanced-diploma-of-leadership-and-management/',
    updated_at = NOW()
WHERE cricos_course_code = '111216E';

UPDATE courses SET
    course_description = '<div class="content"> <p>This qualification reflects the role of individuals working as developing and emerging leaders and managers in a range of enterprise and industry contexts.</p> <p>As well as assuming responsibility for their own performance, individuals at this level are likely to provide leadership, guidance and support to others. They may also have some responsibility for organising and monitoring the output of teams.</p> <p>They apply solutions to a defined range of predictable and unpredictable problems and analyse and evaluate information from a variety of sources.</p> </div>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="content"> <p>There is no pre-requisites or specific entry requirement for this qualification. This course is available to all international students as along as they can provide the evidence that:</p> <ul> <li aria-level="1">The Student must be 18 years or older at the time of course commencement,</li> <li aria-level="1">The Student has successfully completed the Australian Year 12 (or equivalent) and,</li> <li aria-level="1">The Student have an IELTS score of at least 6.0 or PTE Academic score of 50 (or equivalent) OR Successful completion of ELICOS (English for Academic Purposes (EAP) or General English) at Advanced level.</li> <li aria-level="1">Note: Citizens of certain countries are exempted from the English proficiency requirement, please contact AIA for further details or visit the <a href="https://immi.homeaffairs.gov.au/visas/getting-a-visa/visa-listing/student-500#Eligibility" rel="noopener" target="_blank">DOHA Website</a>.</li> </ul> </div>',
    apply_form = 'https://auscanus.edu.au/courses/certificate-iv-in-leadership-and-management/',
    updated_at = NOW()
WHERE cricos_course_code = '111213H';

